let legalCurrentLang = "tr";
const legalPolicyOriginals = new WeakMap();

function scrollToWaitlistPrivacy() {
  if (!/^#waitlist-privacy(?:-(?:tr|en|de))?$/.test(window.location.hash)) return;
  requestAnimationFrame(() => {
    document.getElementById("waitlist-privacy-" + legalCurrentLang)?.scrollIntoView({ block: "start", behavior: "instant" });
  });
}

function detectLegalLang() {
  try {
    const params = new URLSearchParams(window.location.search);
    const qLang = params.get("lang");
    if (qLang && (LEGAL_I18N[qLang.toLowerCase()] || LEGAL_NOTE_LANGS[qLang.toLowerCase()])) {
      return qLang.toLowerCase();
    }
  } catch {}

  const saved = localStorage.getItem("lernfino_web_lang");
  if (saved && (LEGAL_I18N[saved] || LEGAL_NOTE_LANGS[saved])) return saved;

  const nav = (navigator.language || "en").toLowerCase();
  if (nav.startsWith("tr")) return "tr";
  if (nav.startsWith("de")) return "de";
  if (nav.startsWith("en")) return "en";
  return "en";
}

function setLegalLanguage(chosen) {
  const isNote = !LEGAL_I18N[chosen] && !!LEGAL_NOTE_LANGS[chosen];
  if (!LEGAL_I18N[chosen] && !isNote) return;
  const lang = isNote ? "en" : chosen;
  const policyBlocks = document.querySelectorAll("[data-legal-translation]");
  const policyTranslations = policyBlocks.length ? LEGAL_POLICY_TRANSLATIONS[chosen] : undefined;
  const direction = chosen === "ar" ? "rtl" : "ltr";
  legalCurrentLang = lang;
  localStorage.setItem("lernfino_web_lang", chosen);
  document.documentElement.lang = chosen;
  // Keep the English layout and apply text direction to each translated block.
  document.documentElement.dir = "ltr";

  // Binding-language note for the 12 additional languages
  const oldNote = document.getElementById("legalLangNote");
  if (oldNote) oldNote.remove();
  if (isNote) {
    const host = document.querySelector(".legal-card") || document.querySelector(".legal-main");
    if (host) {
      const note = document.createElement("div");
      note.id = "legalLangNote";
      note.className = "callout-box callout-amber";
      note.lang = chosen;
      note.dir = direction;
      const [fallback, binding] = LEGAL_NOTE_LANGS[chosen];
      note.textContent = policyTranslations ? binding : fallback + binding;
      host.insertBefore(note, host.firstChild);
    }
  }
  // Translated error-reports paragraph (only exists on /privacy)
  const errPara = document.getElementById("errorReportsPara");
  if (errPara) {
    if (!errPara.dataset.en) errPara.dataset.en = errPara.innerHTML;
    if (isNote && ERROR_REPORTS_LANGS[chosen]) {
      errPara.innerHTML = ERROR_REPORTS_LANGS[chosen];
      errPara.lang = chosen;
      errPara.dir = direction;
    } else {
      errPara.innerHTML = errPara.dataset.en;
      errPara.removeAttribute("lang");
      errPara.removeAttribute("dir");
    }
  }
  const hosting = document.getElementById("hostingDisclosureEn");
  if (hosting) {
    hosting.dataset.en ??= hosting.textContent;
    hosting.textContent = HOSTING_DISCLOSURES[chosen] ?? hosting.dataset.en;
    hosting.lang = isNote ? chosen : "en";
    hosting.dir = direction;
  }
  const sel = document.getElementById("langSelect");
  if (sel) sel.value = chosen;

  // 1. Update text elements with [data-i18n]
  document.querySelectorAll("[data-i18n]").forEach((el) => {
    const key = el.getAttribute("data-i18n");
    const val = LEGAL_I18N[lang][key];
    const translation = policyTranslations?.[key];
    if (translation !== undefined) {
      el.textContent = translation;
      el.lang = chosen;
      el.dir = direction;
    } else if (val !== undefined) {
      el.innerHTML = val;
      if (key === "meta.dataPolicyUpdated") {
        el.removeAttribute("lang");
        el.removeAttribute("dir");
      }
    }
  });

  policyBlocks.forEach((el) => {
    const translation = policyTranslations?.[el.dataset.legalTranslation];
    if (translation !== undefined) {
      if (!legalPolicyOriginals.has(el)) legalPolicyOriginals.set(el, el.innerHTML);
      el.innerHTML = translation;
      el.lang = chosen;
      el.dir = direction;
    } else if (legalPolicyOriginals.has(el)) {
      el.innerHTML = legalPolicyOriginals.get(el);
      el.removeAttribute("lang");
      el.removeAttribute("dir");
    }
  });

  // 2. Toggle active language buttons
  document.querySelectorAll(".lang-btn").forEach((btn) => {
    const active = btn.getAttribute("data-lang") === chosen;
    btn.classList.toggle("active", active);
    btn.setAttribute("aria-pressed", String(active));
  });

  // 3. Show/hide language-specific content blocks: [data-lang-content="tr|en|de"]
  document.querySelectorAll("[data-lang-content]").forEach((block) => {
    const targetLang = block.getAttribute("data-lang-content");
    if (targetLang === lang) {
      block.style.display = "";
    } else {
      block.style.display = "none";
    }
  });

  scrollToWaitlistPrivacy();

  // 4. Update dynamic email builder if present on /delete-account
  updateDeleteMailto();
}

function updateDeleteMailto() {
  const emailInput =
    document.getElementById(`deleteEmailInput-${legalCurrentLang}`) ||
    document.getElementById("deleteEmailInput");
  const actionBtn =
    document.getElementById(`sendDeleteEmailBtn-${legalCurrentLang}`) ||
    document.getElementById("sendDeleteEmailBtn");
  if (!actionBtn) return;

  const enteredEmail = emailInput ? emailInput.value.trim() : "";
  let subject = "";
  let body = "";

  if (legalCurrentLang === "en") {
    subject = encodeURIComponent("Lernfino Account & Data Deletion Request");
    body = encodeURIComponent(
      `Hello Lernfino Support Team,\n\nI would like to permanently delete my Lernfino account and all associated cloud data.\n\nRegistered Email: ${enteredEmail || "[Enter your email]"}\n\nI understand that deleting my account does not cancel an active App Store or Google Play subscription.\n\nPlease confirm once the deletion is completed.\n\nThank you.`
    );
  } else if (legalCurrentLang === "de") {
    subject = encodeURIComponent("Lernfino Konto- und Datenlöschung");
    body = encodeURIComponent(
      `Hallo Lernfino Support-Team,\n\nich möchte mein Lernfino-Konto und alle zugehörigen Daten dauerhaft löschen.\n\nRegistrierte E-Mail-Adresse: ${enteredEmail || "[Ihre E-Mail-Adresse]"}\n\nMir ist bekannt, dass die Kontolöschung ein aktives App-Store- oder Google-Play-Abonnement nicht automatisch kündigt.\n\nBitte bestätigen Sie die Löschung.\n\nVielen Dank.`
    );
  } else {
    subject = encodeURIComponent("Lernfino Hesap ve Veri Silme Talebi");
    body = encodeURIComponent(
      `Merhaba Lernfino Destek Ekibi,\n\nLernfino hesabımı, bulut yedeklerimi ve sunucularınızdaki tüm kişisel verilerimi kalıcı olarak silmek istiyorum.\n\nKayıtlı E-posta Adresim: ${enteredEmail || "[Kayıtlı e-postanızı buraya yazın]"}\n\nHesap silme işleminin aktif App Store veya Google Play aboneliğimi otomatik iptal etmediğini biliyorum.\n\nİşlem tamamlandığında lütfen tarafıma bilgi veriniz.\n\nTeşekkürler.`
    );
  }

  actionBtn.href = `mailto:support@lernfino.com?subject=${subject}&body=${body}`;
}

document.addEventListener("DOMContentLoaded", () => {
  // 1. Theme Initialization
  const savedTheme = localStorage.getItem("lernfino_web_theme");
  if (savedTheme === "dark" || savedTheme === "light") {
    document.documentElement.setAttribute("data-theme", savedTheme);
  }

  const themeToggle = document.getElementById("themeToggle");
  if (themeToggle) {
    themeToggle.addEventListener("click", () => {
      const current = document.documentElement.getAttribute("data-theme") || "light";
      const next = current === "dark" ? "light" : "dark";
      document.documentElement.setAttribute("data-theme", next);
      localStorage.setItem("lernfino_web_theme", next);
    });
  }

  // 2. Language Switcher Buttons
  const legalSelect = document.getElementById("langSelect");
  if (legalSelect) legalSelect.addEventListener("change", () => setLegalLanguage(legalSelect.value));

  document.querySelectorAll(".lang-btn").forEach((btn) => {
    btn.addEventListener("click", () => {
      const targetLang = btn.getAttribute("data-lang");
      if (targetLang) {
        setLegalLanguage(targetLang);
      }
    });
  });

  // Footer language links
  document.querySelectorAll("[data-lang-switch]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const targetLang = btn.getAttribute("data-lang-switch");
      if (targetLang) {
        setLegalLanguage(targetLang);
      }
    });
  });

  // 3. FAQ Accordion Click Handlers
  document.querySelectorAll(".faq-question").forEach((btn) => {
    btn.addEventListener("click", () => {
      const item = btn.closest(".faq-item");
      if (!item) return;
      const isOpen = item.classList.contains("open");

      const parentList = item.closest(".faq-list");
      if (parentList) {
        parentList.querySelectorAll(".faq-item").forEach((it) => it.classList.remove("open"));
      }

      if (!isOpen) {
        item.classList.add("open");
      }
    });
  });

  // 4. Interactive Deletion Email Builder (unique per language block)
  ["tr", "en", "de"].forEach((code) => {
    const input = document.getElementById(`deleteEmailInput-${code}`);
    if (input) input.addEventListener("input", updateDeleteMailto);
  });
  const legacyDeleteInput = document.getElementById("deleteEmailInput");
  if (legacyDeleteInput) {
    legacyDeleteInput.addEventListener("input", updateDeleteMailto);
  }

  window.addEventListener("hashchange", scrollToWaitlistPrivacy);

  // 5. Initial language render
  setLegalLanguage(detectLegalLang());
});
